"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["12545"],{50773(e){e.exports=JSON.parse('{"id":"FIN-031","slug":"cost-of-living","term":"Cost of Living","also_known_as":[],"difficulty":"Beginner","definition":"The cost of living is the amount of money needed to pay for a basic standard of living in a particular place and time, including housing, food, transport, healthcare and other everyday necessities.","explanation":["The cost of living varies widely between countries, cities and even neighbourhoods. Rent for a small flat in a large capital city might be three times higher than in a smaller town in the same country, even if wages are not three times higher.","It also changes over time. When prices for essentials such as food, energy and rent rise faster than wages, people talk about a cost-of-living crisis, because the same income covers less.","Comparing salaries without considering the cost of living can be misleading. A job paying 60,000 in a city where rent is 2,000 a month may leave less spare money than a job paying 45,000 where rent is 900.","Governments and employers use cost-of-living measures to adjust pensions, benefits and wages. Many countries link some payments to a price index, such as the Consumer Price Index, so they rise with living costs. Employers sometimes add allowances for staff who work in expensive locations."],"note":"","total":1500,"prev":{"slug":"cost-of-goods-sold","term":"Cost of Goods Sold"},"next":{"slug":"cost-push-inflation","term":"Cost-Push Inflation"}}')}}]);